css:
.execgap-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #eef2f7 0%, #dce3ed 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.execgap-sim-container .execgap-sim-header {
    background: linear-gradient(135deg, #1a2a4a 0%, #2c3e6b 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 25px;
    box-shadow: 0 8px 24px rgba(26,42,74,0.3);
    text-align: center;
}

.execgap-sim-container .execgap-sim-header h1 {
    font-size: 1.8rem;
    font-weight: 700;
    margin-bottom: 8px;
}

.execgap-sim-container .execgap-sim-header p {
    font-size: 1rem;
    opacity: 0.85;
    margin-bottom: 0;
}

.execgap-sim-container .execgap-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    color: #555;
    margin-bottom: 20px;
    font-weight: 600;
}

.execgap-sim-container .execgap-sim-briefing {
    background: linear-gradient(135deg, #fff8e1 0%, #fff3cd 100%);
    border-left: 5px solid #f0ad4e;
    border-radius: 12px;
    padding: 20px 25px;
    margin-bottom: 25px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}

.execgap-sim-container .execgap-sim-briefing h4 {
    color: #856404;
    font-size: 1rem;
    font-weight: 700;
    margin-bottom: 10px;
}

.execgap-sim-container .execgap-sim-briefing p {
    color: #664d03;
    font-size: 0.95rem;
    line-height: 1.6;
    margin-bottom: 0;
}

.execgap-sim-container .execgap-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 15px;
    margin-bottom: 25px;
}

.execgap-sim-container .execgap-sim-status-card {
    background: white;
    border-radius: 14px;
    padding: 20px 15px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    transition: transform 0.3s ease;
    text-align: center;
    border-top: 4px solid #ddd;
}

.execgap-sim-container .execgap-sim-status-card:hover {
    transform: translateY(-4px);
}

.execgap-sim-container .execgap-sim-card-budget { border-top-color: #27ae60; }
.execgap-sim-container .execgap-sim-card-coherence { border-top-color: #2980b9; }
.execgap-sim-container .execgap-sim-card-resistance { border-top-color: #e74c3c; }
.execgap-sim-container .execgap-sim-card-execution { border-top-color: #8e44ad; }
.execgap-sim-container .execgap-sim-card-morale { border-top-color: #f39c12; }
.execgap-sim-container .execgap-sim-card-revenue { border-top-color: #16a085; }

.execgap-sim-container .execgap-sim-label {
    color: #777;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.execgap-sim-container .execgap-sim-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #333;
}

.execgap-sim-container .execgap-sim-controls {
    background: white;
    border-radius: 16px;
    padding: 25px;
    margin-bottom: 25px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.execgap-sim-container .execgap-sim-controls h3 {
    color: #1a2a4a;
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 20px;
    text-align: center;
}

.execgap-sim-container .execgap-sim-decision-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
    margin-bottom: 20px;
}

.execgap-sim-container .execgap-sim-decision-group label {
    font-weight: 600;
    color: #333;
    font-size: 0.9rem;
    margin-bottom: 6px;
    display: block;
}

.execgap-sim-container .execgap-sim-decision-group .form-control {
    border-radius: 8px;
    border: 2px solid #e0e0e0;
    padding: 10px 14px;
    font-size: 1rem;
    transition: border-color 0.3s;
}

.execgap-sim-container .execgap-sim-decision-group .form-control:focus {
    border-color: #2c3e6b;
    box-shadow: 0 0 0 3px rgba(44,62,107,0.15);
}

.execgap-sim-container .execgap-sim-decision-group small {
    font-size: 0.78rem;
    color: #888;
}

.execgap-sim-container .execgap-sim-actions {
    text-align: center;
    padding-top: 10px;
}

.execgap-sim-container .execgap-sim-actions .btn-primary {
    background: linear-gradient(135deg, #1a2a4a 0%, #2c3e6b 100%);
    border: none;
    border-radius: 10px;
    padding: 12px 40px;
    font-size: 1rem;
    font-weight: 600;
    margin-right: 12px;
}

.execgap-sim-container .execgap-sim-actions .btn-outline-secondary {
    border-radius: 10px;
}

.execgap-sim-container .execgap-sim-history {
    margin-bottom: 25px;
}

.execgap-sim-container .execgap-sim-charts {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
    margin-bottom: 30px;
}

.execgap-sim-container .execgap-sim-chart-wrapper {
    background: white;
    border-radius: 14px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    min-height: 280px;
    position: relative;
}

@media (max-width: 768px) {
    .execgap-sim-container .execgap-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .execgap-sim-container .execgap-sim-decision-grid {
        grid-template-columns: 1fr;
    }
    .execgap-sim-container .execgap-sim-charts {
        grid-template-columns: 1fr;
    }
    .execgap-sim-container .execgap-sim-header h1 {
        font-size: 1.3rem;
    }
}

