            var title = this._t('q' + n + '_title'); if (title === 'q' + n + '_title') title = round.title;
            var desc = this._t('q' + n + '_desc'); if (desc === 'q' + n + '_desc') desc = round.description;
            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = '<strong>' + title + '</strong><br><br>' + desc;
            }
        }
